// BlazeGrid docs: a small hash-routed single-page app over data/api.json (generated by tools/DocGen)
// and the Markdown guides in guides/.
//
// Routes:  #/                      home
//          #/guide/<slug>          a guide
//          #/api/<Type>[/<Member>] a type page, optionally opened at a member
//          #/css                   CSS variables
(function () {
    'use strict';

    const KIND_ORDER = ['param', 'event', 'property', 'method', 'value'];
    const KIND_LABEL = { param: 'Parameters', event: 'Events', property: 'Properties', method: 'Methods', value: 'Values' };
    const KIND_SINGULAR = { param: 'parameter', event: 'event', property: 'property', method: 'method', value: 'value' };
    const TYPE_BADGE = { component: 'C', class: 'c', record: 'R', enum: 'E' };

    const $ = (sel, root = document) => root.querySelector(sel);
    const el = (html) => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; };
    const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
    const strip = (html) => { const d = document.createElement('div'); d.innerHTML = html || ''; return d.textContent || ''; };
    // The first sentence of a description ("e.g." and "i.e." don't end a sentence).
    const firstSentence = (html) => { const t = strip(html); const m = t.match(/^.*?(?<!\be\.g|\bi\.e)[.!?](?=\s|$)/); return (m ? m[0] : t).trim(); };

    const store = {
        get(k) { try { return localStorage.getItem(k); } catch { return null; } },
        set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } }
    };

    let api = null;
    let guides = [];
    const guideCache = new Map();
    let searchIndex = [];

    // ------------------------------------------------------------------ boot

    Promise.all([
        fetch('data/api.json').then((r) => r.json()),
        fetch('guides/guides.json').then((r) => r.json())
    ]).then(([a, g]) => {
        api = a;
        guides = g;
        $('#version').textContent = 'v' + api.version;
        if (window.hljs) hljs.registerAliases(['razor', 'cshtml'], { languageName: 'xml' });
        buildNav();
        buildSearchIndex();
        window.addEventListener('hashchange', route);
        route();
    }).catch((err) => {
        $('#content').innerHTML = `<div class="doc"><h1>Couldn't load the docs</h1>
            <p>${esc(err.message)}</p><p>The docs read JSON files, so they must be served over HTTP (not opened as a file).</p></div>`;
    });

    // ------------------------------------------------------------------ routing

    function route() {
        const hash = decodeURIComponent(location.hash.replace(/^#\/?/, ''));
        const [section, a, b] = hash.split('/');
        document.body.classList.remove('nav-open');
        $('#toc').innerHTML = '';
        if (section === 'api' && api.types[a]) renderType(a, b);
        else if (section === 'guide' && guides.some((g) => g.slug === a)) renderGuide(a);
        else if (section === 'css') renderCss(a);
        else renderHome();
        markActiveNav();
    }

    function setTitle(t) { document.title = t ? `${t} · BlazeGrid Docs` : 'BlazeGrid Docs'; }

    // ------------------------------------------------------------------ navigation tree

    function buildNav() {
        const nav = $('#nav');
        const open = (name) => store.get('bzdocs-nav-' + name) !== 'closed';
        const group = (name, items) => {
            const d = el(`<details class="nav-group" ${open(name) ? 'open' : ''}><summary>${esc(name)}</summary></details>`);
            d.addEventListener('toggle', () => store.set('bzdocs-nav-' + name, d.open ? 'open' : 'closed'));
            items.forEach((i) => d.appendChild(i));
            nav.appendChild(d);
        };
        const item = (href, badgeClass, badge, label) =>
            el(`<a class="nav-item" href="${href}" data-label="${esc(label.toLowerCase())}"><span class="kbadge ${badgeClass}">${badge}</span>${esc(label)}</a>`);

        group('Guides', guides.map((g) => item(`#/guide/${g.slug}`, 'k-guide', '¶', g.title)));
        api.groups.forEach((g) => group(g.name, g.types.map((name) => {
            const t = api.types[name];
            return item(`#/api/${name}`, 'k-' + t.kind, TYPE_BADGE[t.kind] || '·', name);
        })));
        group('Styling', [item('#/css', 'k-css', '#', 'CSS variables'), item('#/guide/styling', 'k-guide', '¶', 'Styling & themes')]);

        $('#navFilter').addEventListener('input', (e) => {
            const q = e.target.value.trim().toLowerCase();
            nav.querySelectorAll('.nav-group').forEach((g) => {
                let any = false;
                g.querySelectorAll('.nav-item').forEach((a) => {
                    const show = !q || a.dataset.label.includes(q);
                    a.hidden = !show;
                    any = any || show;
                });
                g.hidden = !any;
                if (q && any) g.open = true;
            });
        });
        $('#navToggle').addEventListener('click', () => document.body.classList.toggle('nav-open'));
    }

    function markActiveNav() {
        const parts = location.hash.split('/');
        const hash = parts[1] === 'css' ? '#/css' : parts.slice(0, 3).join('/') || '#/';
        document.querySelectorAll('.nav-item').forEach((a) => a.classList.toggle('active', a.getAttribute('href') === hash));
        const active = $('.nav-item.active');
        if (active) {
            active.closest('details').open = true;
            const r = active.getBoundingClientRect();
            const s = $('#sidebar').getBoundingClientRect();
            if (r.top < s.top + 50 || r.bottom > s.bottom) active.scrollIntoView({ block: 'center' });
        }
    }

    // ------------------------------------------------------------------ home

    function renderHome() {
        setTitle('');
        const grid = api.types.BzGrid, col = api.types.BzColumn;
        const count = (t, k) => t.members.filter((m) => m.kind === k).length;
        const content = $('#content');
        content.innerHTML = `
            <div class="doc">
                <section class="hero">
                    <h1><svg viewBox="0 0 32 32" width="40" height="40" aria-hidden="true"><path d="M18 2 6 18h8l-2 12 12-16h-8z" fill="#f59e0b"/></svg>BlazeGrid</h1>
                    <p>A virtualized data grid for Blazor WebAssembly: only the rows on screen are rendered, and filtering,
                       sorting and grouping can run in a Web Worker. Built for the shortest path from data received to pixels on screen.</p>
                    <div class="hero-actions">
                        <a class="btn primary" href="#/guide/getting-started">Get started</a>
                        <a class="btn" href="#/api/BzGrid">API reference</a>
                    </div>
                </section>
                <pre><code class="language-razor">${esc(`<BzGrid TItem="Order" Items="orders" Height="600px" PageSize="100" StateKey="orders">
    <BzColumn Field="Id" Title="#" Locked="ColumnLock.Left" />
    <BzColumn Field="Customer.Name" Title="Customer" Filter="FilterKind.MultiSelect" />
    <BzColumn Field="OrderDate" Format="yyyy-MM-dd" />
    <BzColumn Field="Amount" Format="C2" />
</BzGrid>`)}</code></pre>
                <div class="section-title">Reference</div>
                <div class="cards">
                    <a class="card" href="#/api/BzGrid"><b><span class="kbadge k-component">C</span>BzGrid&lt;TItem&gt;</b>
                        <span>${count(grid, 'param')} parameters · ${count(grid, 'event')} events · ${count(grid, 'method')} methods</span></a>
                    <a class="card" href="#/api/BzColumn"><b><span class="kbadge k-component">C</span>BzColumn&lt;TItem&gt;</b>
                        <span>${count(col, 'param')} parameters: fields, formats, templates, features</span></a>
                    <a class="card" href="#/css"><b><span class="kbadge k-css">#</span>CSS variables</b>
                        <span>${api.cssVariables.length} --bz-* variables with default and dark values</span></a>
                </div>
                <div class="section-title">Guides</div>
                <div class="cards">${guides.map((g) => `<a class="card" href="#/guide/${g.slug}"><b>${esc(g.title)}</b><span>${esc(g.summary)}</span></a>`).join('')}</div>
                <div class="section-title">Most used</div>
                <div class="chips">${[
                    ['BzGrid', 'Items'], ['BzGrid', 'PageSize'], ['BzGrid', 'StateKey'], ['BzGrid', 'ServerMode'], ['BzGrid', 'OnQueryChanged'],
                    ['BzGrid', 'OnRowUpdated'], ['BzGrid', 'RowClass'], ['BzColumn', 'Field'], ['BzColumn', 'Format'], ['BzColumn', 'Template'],
                    ['BzColumn', 'Filter'], ['BzColumn', 'CellClassSelector'], ['BzColumn', 'FooterTemplate'], ['BzGrid', 'FindColumn']
                ].map(([t, m]) => `<a class="chip" href="#/api/${t}/${m}">${t}.${m}</a>`).join('')}</div>
                <p class="section-title" style="margin-top:36px">v${esc(api.version)} · generated ${esc(api.generated)}</p>
            </div>`;
        enhanceCode(content);
        content.scrollTop = 0;
        window.scrollTo(0, 0);
    }

    // ------------------------------------------------------------------ type page

    function renderType(name, memberName) {
        const t = api.types[name];
        setTitle(name);
        const groupName = api.groups.find((g) => g.types.includes(name))?.name || 'API';
        const byKind = Object.fromEntries(KIND_ORDER.map((k) => [k, t.members.filter((m) => m.kind === k)]));
        const kinds = KIND_ORDER.filter((k) => byKind[k].length);
        const content = $('#content');

        content.innerHTML = `
            <div class="crumbs">API › ${esc(groupName)}</div>
            <header class="type-head">
                <h1 class="type-title"><code>${esc(t.display)}</code><span class="kind-pill k-${t.kind}">${t.kind}</span></h1>
                <div class="type-meta">
                    <span>namespace <code>${esc(t.namespace)}</code></span>
                    ${t.base ? `<span>inherits ${linkTypes(t.base)}</span>` : ''}
                    <span>${t.members.length} members</span>
                </div>
                <div class="prose type-summary">${t.summary || '<p class="muted">No description.</p>'}</div>
                ${t.remarks ? `<div class="prose remarks">${t.remarks}</div>` : ''}
                ${t.example ? `<div class="example-label">Example</div><div class="prose">${t.example}</div>` : ''}
            </header>
            ${kinds.length ? `
            <div class="member-bar">
                <input class="member-filter" type="search" placeholder="Filter members…" aria-label="Filter members" />
                ${kinds.map((k) => `<button class="kind-toggle" data-kind="${k}" aria-pressed="true">
                    <span class="dot" style="background:var(--k-${k})"></span>${KIND_LABEL[k]}<span class="n">${byKind[k].length}</span></button>`).join('')}
                <span class="bar-spacer"></span>
                <button class="text-btn" data-act="expand">Expand all</button>
                <button class="text-btn" data-act="collapse">Collapse all</button>
            </div>` : ''}
            <div class="members">
                ${kinds.map((k) => renderKindSection(name, k, byKind[k])).join('')}
                <div class="no-match" hidden>No members match.</div>
            </div>`;

        enhanceCode(content);
        wireMemberBar(content);
        content.querySelectorAll('.m-head').forEach((h) => h.addEventListener('click', () => toggleMember(h.closest('.member'))));

        // On-this-page rail: kinds and their categories.
        $('#toc').innerHTML = kinds.length ? `<div class="toc-title">On this page</div>` + kinds.map((k) => {
            const cats = [...new Set(byKind[k].map((m) => m.category))];
            return `<a href="#" data-target="kind-${k}">${KIND_LABEL[k]}</a>` +
                (cats.length > 1 ? cats.map((c) => `<a class="sub" href="#" data-target="cat-${k}-${slug(c)}">${esc(c)}</a>`).join('') : '');
        }).join('') : '';
        $('#toc').querySelectorAll('a[data-target]').forEach((a) => a.addEventListener('click', (e) => {
            e.preventDefault();
            const target = document.getElementById(a.dataset.target);
            if (target) scrollBelowBars(target, 'smooth');
        }));

        if (memberName) {
            const m = document.getElementById('m-' + memberName);
            if (m) {
                toggleMember(m, true);
                requestAnimationFrame(() => {
                    scrollBelowBars(m);
                    m.classList.remove('flash');
                    void m.offsetWidth;
                    m.classList.add('flash');
                });
                return;
            }
        }
        window.scrollTo(0, 0);
    }

    function renderKindSection(typeName, kind, members) {
        let html = `<section class="kind-section" id="kind-${kind}" data-kind="${kind}">
            <h2><span class="dot" style="background:var(--k-${kind})"></span>${KIND_LABEL[kind]}<span class="n">${members.length}</span></h2>`;
        const cats = [...new Set(members.map((m) => m.category))];
        for (const c of cats) {
            if (cats.length > 1 || (c !== KIND_LABEL[kind] && c !== 'Values')) html += `<div class="cat" id="cat-${kind}-${slug(c)}">${esc(c)}</div>`;
            html += members.filter((m) => m.category === c).map((m) => renderMember(typeName, m)).join('');
        }
        return html + '</section>';
    }

    function renderMember(typeName, m) {
        const isMethod = m.kind === 'method';
        const sig = isMethod
            ? `<span class="m-name">${esc(m.name)}</span><span class="m-type">(${(m.params || []).map((p) => esc(p.name)).join(', ')}) : ${linkTypes(m.type)}</span>`
            : `<span class="m-name">${esc(m.name)}</span><span class="m-type"> : ${linkTypes(m.type)}</span>`;
        const def = m.default != null && m.default !== 'null' && m.kind !== 'value'
            ? `<span class="m-default">= <b>${esc(m.default)}</b></span>` : (m.kind === 'value' ? `<span class="m-default">= <b>${esc(m.default)}</b></span>` : '<span></span>');
        const tags = [];
        tags.push(`<span class="tag">${KIND_SINGULAR[m.kind]}</span>`);
        if (m.access) tags.push(`<span class="tag">${esc(m.access)}</span>`);
        if (m.required) tags.push(`<span class="tag req">required</span>`);
        const body = `
            <div class="tags">${tags.join('')}<a class="permalink" href="#/api/${typeName}/${m.name}" title="Link to this member">#${esc(m.name)}</a></div>
            ${isMethod ? `<pre><code class="language-csharp">${esc(m.signature)}</code></pre>` : ''}
            <div class="prose">${m.summary || '<p>No description.</p>'}</div>
            ${m.remarks ? `<div class="prose remarks">${m.remarks}</div>` : ''}
            ${m.params ? `<table class="params"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody>
                ${m.params.map((p) => `<tr><td>${esc(p.name)}</td><td class="t">${linkTypes(p.type)}${p.default != null ? ` = ${esc(p.default)}` : ''}</td><td class="prose">${p.summary || ''}</td></tr>`).join('')}
                </tbody></table>` : ''}
            ${m.returns ? `<div class="prose"><b>Returns</b> ${linkTypes(m.type)}: ${m.returns}</div>` : ''}
            ${m.example ? `<div class="example-label">Example</div><div class="prose">${m.example}</div>` : ''}`;
        return `<div class="member" id="m-${esc(m.name)}" data-name="${esc(m.name.toLowerCase())}" data-text="${esc((m.name + ' ' + strip(m.summary)).toLowerCase())}">
            <button class="m-head" aria-expanded="false"><span class="m-chev"></span><span class="m-sig">${sig}</span>
                <span class="m-short">${esc(firstSentence(m.summary))}</span>${def}</button>
            <div class="m-body">${body}</div></div>`;
    }

    // Scrolls so the element sits just under the sticky top bar and member toolbar (whose height varies with width).
    function scrollBelowBars(target, behavior = 'auto') {
        const bar = $('.member-bar');
        const offset = $('.topbar').offsetHeight + (bar ? bar.offsetHeight : 0) + 8;
        window.scrollTo({ top: target.getBoundingClientRect().top + window.scrollY - offset, behavior });
    }

    function toggleMember(m, force) {
        const open = force ?? !m.classList.contains('open');
        m.classList.toggle('open', open);
        m.querySelector('.m-head').setAttribute('aria-expanded', String(open));
    }

    function wireMemberBar(content) {
        const filter = $('.member-filter', content);
        if (!filter) return;
        const apply = () => {
            const q = filter.value.trim().toLowerCase();
            const off = new Set([...content.querySelectorAll('.kind-toggle[aria-pressed="false"]')].map((b) => b.dataset.kind));
            let shown = 0;
            content.querySelectorAll('.kind-section').forEach((sec) => {
                let any = false;
                sec.querySelectorAll('.member').forEach((m) => {
                    const match = !off.has(sec.dataset.kind) && (!q || m.dataset.text.includes(q));
                    m.classList.toggle('hidden-by-filter', !match);
                    any = any || match;
                    if (match) shown++;
                });
                sec.hidden = !any;
                sec.querySelectorAll('.cat').forEach((c) => {
                    let n = c.nextElementSibling, vis = false;
                    while (n && n.classList.contains('member')) { vis = vis || !n.classList.contains('hidden-by-filter'); n = n.nextElementSibling; }
                    c.hidden = !vis;
                });
            });
            $('.no-match', content).hidden = shown > 0;
        };
        filter.addEventListener('input', apply);
        content.querySelectorAll('.kind-toggle').forEach((b) => b.addEventListener('click', () => {
            b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
            apply();
        }));
        content.querySelector('[data-act="expand"]').addEventListener('click', () =>
            content.querySelectorAll('.member:not(.hidden-by-filter)').forEach((m) => toggleMember(m, true)));
        content.querySelector('[data-act="collapse"]').addEventListener('click', () =>
            content.querySelectorAll('.member').forEach((m) => toggleMember(m, false)));
    }

    // Wraps documented type names inside a C# type string with links: "EventCallback<RowEventArgs<TItem>>".
    function linkTypes(typeStr) {
        return esc(typeStr).replace(/\b([A-Z]\w*)\b/g, (w) => api.types[w] ? `<a href="#/api/${w}">${w}</a>` : w);
    }

    // ------------------------------------------------------------------ guides

    function renderGuide(slugName) {
        const g = guides.find((x) => x.slug === slugName);
        setTitle(g.title);
        const content = $('#content');
        const show = (md) => {
            const idx = guides.indexOf(g);
            const prev = guides[idx - 1], next = guides[idx + 1];
            content.innerHTML = `<article class="doc">${window.marked ? marked.parse(md) : `<pre>${esc(md)}</pre>`}
                <nav class="guide-nav">
                    ${prev ? `<a class="prev" href="#/guide/${prev.slug}"><small>Previous</small>${esc(prev.title)}</a>` : ''}
                    ${next ? `<a class="next" href="#/guide/${next.slug}"><small>Next</small>${esc(next.title)}</a>` : ''}
                </nav></article>`;
            const heads = [...content.querySelectorAll('.doc h2, .doc h3')];
            heads.forEach((h) => { h.id = 'h-' + slug(h.textContent); });
            $('#toc').innerHTML = heads.length ? `<div class="toc-title">On this page</div>` +
                heads.map((h) => `<a href="#" class="${h.tagName === 'H3' ? 'sub' : ''}" data-target="${h.id}">${esc(h.textContent)}</a>`).join('') : '';
            $('#toc').querySelectorAll('a[data-target]').forEach((a) => a.addEventListener('click', (e) => {
                e.preventDefault();
                document.getElementById(a.dataset.target)?.scrollIntoView({ behavior: 'smooth' });
            }));
            enhanceCode(content);
            window.scrollTo(0, 0);
        };
        if (guideCache.has(slugName)) return show(guideCache.get(slugName));
        content.innerHTML = '<div class="loading">Loading…</div>';
        fetch(`guides/${slugName}.md`).then((r) => r.text()).then((md) => { guideCache.set(slugName, md); show(md); });
    }

    // ------------------------------------------------------------------ CSS variables

    function renderCss(focus) {
        setTitle('CSS variables');
        const isColor = (v) => /^(#|rgb|hsl)/.test(v);
        const sw = (v) => isColor(v) ? `<span class="swatch" style="background:${esc(v)}"></span>` : '';
        const starter = '.my-grid {\n' + api.cssVariables.map((v) => `    ${v.name}: ${v.value};`).join('\n') + '\n}';
        const content = $('#content');
        content.innerHTML = `
            <div class="doc">
                <div class="crumbs">Styling</div>
                <h1>CSS variables</h1>
                <p>Every visual of the grid comes from these variables, declared on <code>.bz-grid</code>. Override them on your own class
                   (<code>Class="my-grid"</code>), on a theme class (<code>Theme="x"</code> → <code>.bz-theme-x</code>), or inline with the
                   <a href="#/api/BzGrid/Style"><code>Style</code></a> parameter. See <a href="#/guide/styling">Styling & themes</a> for class names and examples.</p>
                <table class="vars">
                    <thead><tr><th>Variable</th><th>Default</th><th>Dark theme</th><th>Controls</th></tr></thead>
                    <tbody>${api.cssVariables.map((v) => `<tr id="var-${esc(v.name.slice(5))}">
                        <td class="v"><b>${esc(v.name)}</b></td>
                        <td class="v">${sw(v.value)}${esc(v.value)}</td>
                        <td class="v">${v.dark ? sw(v.dark) + esc(v.dark) : '<span style="color:var(--muted)">same</span>'}</td>
                        <td>${esc(v.description || '')}</td></tr>`).join('')}</tbody>
                </table>
                <h2>Theme starter</h2>
                <p>Every variable with its default, ready to copy into your stylesheet. Delete the lines you don't change.</p>
                <pre><code class="language-css">${esc(starter)}</code></pre>
            </div>`;
        enhanceCode(content);
        const row = focus && document.getElementById('var-' + focus);
        if (row) { scrollBelowBars(row); row.classList.add('flash'); }
        else window.scrollTo(0, 0);
    }

    // ------------------------------------------------------------------ search

    function buildSearchIndex() {
        searchIndex = [];
        for (const [name, t] of Object.entries(api.types)) {
            searchIndex.push({ label: t.display, key: name.toLowerCase(), sub: t.kind + ' · ' + firstSentence(t.summary), href: `#/api/${name}`, rank: 0, badge: TYPE_BADGE[t.kind], cls: 'k-' + t.kind });
            for (const m of t.members) {
                searchIndex.push({ label: m.name, key: m.name.toLowerCase(), sub: `${name} · ${KIND_SINGULAR[m.kind]} · ${firstSentence(m.summary)}`,
                    href: `#/api/${name}/${m.name}`, rank: name === 'BzGrid' || name === 'BzColumn' ? 1 : 2 });
            }
        }
        for (const g of guides) searchIndex.push({ label: g.title, key: g.title.toLowerCase(), sub: 'guide · ' + g.summary, href: `#/guide/${g.slug}`, rank: 1, badge: '¶', cls: 'k-guide' });
        for (const v of api.cssVariables) searchIndex.push({ label: v.name, key: v.name.toLowerCase(), sub: 'CSS variable · ' + (v.description || ''), href: `#/css/${v.name.slice(5)}`, rank: 2, badge: '#', cls: 'k-css' });
    }

    function search(q) {
        q = q.trim().toLowerCase();
        if (!q) return [];
        const scored = [];
        for (const e of searchIndex) {
            let s;
            if (e.key === q) s = 0;
            else if (e.key.startsWith(q)) s = 1;
            else if (e.key.includes(q)) s = 2;
            else if (e.sub.toLowerCase().includes(q)) s = 4;
            else continue;
            scored.push([s * 10 + e.rank, e]);
        }
        return scored.sort((a, b) => a[0] - b[0] || a[1].label.localeCompare(b[1].label)).slice(0, 14).map((x) => x[1]);
    }

    (function wireSearch() {
        const input = $('#searchInput');
        const box = $('#searchResults');
        let results = [], active = 0;
        const render = () => {
            if (!input.value.trim()) { box.hidden = true; return; }
            box.hidden = false;
            box.innerHTML = results.length
                ? results.map((r, i) => `<a class="sr-item ${i === active ? 'active' : ''}" href="${r.href}" role="option" data-i="${i}">
                    ${r.badge ? `<span class="kbadge ${r.cls}">${r.badge}</span>` : '<span class="kbadge" style="background:var(--k-param)">·</span>'}
                    <span class="sr-label">${esc(r.label)}</span><span class="sr-sub">${esc(r.sub)}</span></a>`).join('')
                : `<div class="sr-empty">Nothing matches "${esc(input.value)}".</div>`;
        };
        const go = (r) => { if (!r) return; input.value = ''; box.hidden = true; input.blur(); location.hash = r.href; };
        input.addEventListener('input', () => { results = api ? search(input.value) : []; active = 0; render(); });
        input.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowDown') { active = Math.min(active + 1, results.length - 1); render(); e.preventDefault(); }
            else if (e.key === 'ArrowUp') { active = Math.max(active - 1, 0); render(); e.preventDefault(); }
            else if (e.key === 'Enter') { go(results[active]); e.preventDefault(); }
            else if (e.key === 'Escape') { input.value = ''; box.hidden = true; input.blur(); }
        });
        box.addEventListener('mousedown', (e) => { const a = e.target.closest('.sr-item'); if (a) { e.preventDefault(); go(results[+a.dataset.i]); } });
        input.addEventListener('blur', () => setTimeout(() => { box.hidden = true; }, 120));
        input.addEventListener('focus', () => { if (input.value.trim()) render(); });
        document.addEventListener('keydown', (e) => {
            if (e.key === '/' && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) { e.preventDefault(); input.focus(); }
        });
    })();

    // ------------------------------------------------------------------ shared helpers

    function enhanceCode(root) {
        root.querySelectorAll('pre > code').forEach((code) => {
            if (code.dataset.done) return;
            code.dataset.done = '1';
            if (window.hljs) {
                if (!/language-/.test(code.className)) code.className += ' language-csharp';
                try { hljs.highlightElement(code); } catch { /* unknown language: leave plain */ }
            }
            const btn = el('<button class="copy-btn" type="button">Copy</button>');
            btn.addEventListener('click', () => {
                navigator.clipboard?.writeText(code.textContent).then(() => {
                    btn.textContent = 'Copied';
                    setTimeout(() => { btn.textContent = 'Copy'; }, 1200);
                });
            });
            code.parentElement.appendChild(btn);
        });
    }

    function slug(s) { return String(s).toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

    $('#themeToggle').addEventListener('click', () => {
        const root = document.documentElement;
        const dark = root.getAttribute('data-theme') === 'dark' ||
            (!root.getAttribute('data-theme') && matchMedia('(prefers-color-scheme: dark)').matches);
        const next = dark ? 'light' : 'dark';
        root.setAttribute('data-theme', next);
        store.set('bzdocs-theme', next);
    });
})();
